<section class="seat-selection">
  <h1 data-testid="seat-map-title">Choose your seats</h1>

  @if (data.value(); as loaded) {
    <p class="subtitle" data-testid="seat-map-subtitle">Show Date: {{ loaded.showDate }}</p>

    <div class="auditorium">
      <p class="seat-limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>
      <div class="screen" data-testid="screen-indicator">SCREEN</div>

      <div class="seat-map" data-testid="seat-map">
        @for (row of rows(); track row.number) {
          <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.number">
            <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.number">{{ row.number }}</span>
            @for (slot of row.slots; track slot.key) {
              @if (slot.kind === 'seat') {
                <button
                  type="button"
                  class="seat"
                  data-testid="seat"
                  [attr.data-row]="slot.row"
                  [attr.data-column]="slot.column"
                  [attr.data-state]="slot.state"
                  [disabled]="slot.state === 'unavailable'"
                >{{ slot.column }}</button>
              } @else if (slot.kind === 'couch') {
                <button
                  type="button"
                  class="couch"
                  data-testid="couch"
                  [attr.data-row]="slot.row"
                  [attr.data-column-start]="slot.start"
                  [attr.data-column-end]="slot.end"
                  [attr.data-state]="slot.state"
                  [disabled]="slot.state === 'unavailable'"
                >{{ slot.start }}-{{ slot.end }}</button>
              } @else if (slot.kind === 'aisle') {
                <span class="aisle" data-testid="aisle" [attr.data-row]="slot.row"></span>
              } @else {
                <span class="entrance" aria-hidden="true"></span>
              }
            }
            <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.number">{{ row.number }}</span>
          </div>
        }
      </div>
    </div>
  }
</section>
