==== seat-selection/seat-selection.ts
import { Component, effect, inject, input, resource, computed, signal } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { Title } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { CinemaApi } from '../cinema-api';
import { formatShowDate } from '../dates';
import { Movie, Screening } from '../models';
import { Toast } from '../toast';

const ROW_NUMBERS = Array.from({ length: 15 }, (_, index) => index + 1);
/** Rows 1 to 10 have no seats in columns 1 to 4; that space is the entrance. */
const LAST_ENTRANCE_ROW = 10;
/** Row 15 is made of couches only. */
const COUCH_ROW = 15;
const ACCESSIBLE_ROW = 1;
const ACCESSIBLE_FIRST_COLUMN = 10;
const ACCESSIBLE_LAST_COLUMN = 15;
/** A booking holds at most this many seats; a couch counts as two. */
const MAX_SEATS = 10;

export type SeatState = 'available' | 'unavailable' | 'accessible';
type DisplayState = SeatState | 'selected';

type Slot =
  | { kind: 'seat'; key: string; row: number; column: number; state: SeatState }
  | { kind: 'couch'; key: string; row: number; start: number; end: number; state: SeatState }
  | { kind: 'aisle'; key: string; row: number }
  | { kind: 'entrance'; key: string };

/** A seat or a couch: the elements that can be selected. */
type Bookable = Extract<Slot, { state: SeatState }>;

interface SeatMapRow {
  number: number;
  slots: Slot[];
}

interface SeatMapData {
  movie: Movie;
  screening: Screening;
  showDate: string;
}

interface SelectedRow {
  row: number;
  seats: string;
}

const LEGEND: { state: DisplayState; label: string }[] = [
  { state: 'available', label: 'Available' },
  { state: 'selected', label: 'Selected' },
  { state: 'unavailable', label: 'Unavailable' },
  { state: 'accessible', label: 'Accessible' },
];

function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

function seatState(row: number, column: number, occupied: Set<string>): SeatState {
  if (occupied.has(seatId(row, column))) {
    return 'unavailable';
  }
  const accessible =
    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
  return accessible ? 'accessible' : 'available';
}

/** Slots for the columns `from`..`to` of a row: single seats, or couches of two columns in row 15. */
function segment(row: number, from: number, to: number, occupied: Set<string>): Slot[] {
  const slots: Slot[] = [];
  if (row === COUCH_ROW) {
    for (let start = from; start <= to; start += 2) {
      const end = start + 1;
      const unavailable = occupied.has(seatId(row, start)) || occupied.has(seatId(row, end));
      slots.push({
        kind: 'couch',
        key: `couch-${row}-${start}`,
        row,
        start,
        end,
        state: unavailable ? 'unavailable' : 'available',
      });
    }
    return slots;
  }
  for (let column = from; column <= to; column++) {
    slots.push({
      kind: 'seat',
      key: `seat-${row}-${column}`,
      row,
      column,
      state: seatState(row, column, occupied),
    });
  }
  return slots;
}

function aisle(row: number, after: number): Slot {
  return { kind: 'aisle', key: `aisle-${row}-${after}`, row };
}

function buildRow(row: number, occupied: Set<string>): Slot[] {
  const left: Slot[] =
    row <= LAST_ENTRANCE_ROW
      ? [{ kind: 'entrance', key: `entrance-${row}` }]
      : segment(row, 1, 4, occupied);
  return [
    ...left,
    aisle(row, 4),
    ...segment(row, 5, 20, occupied),
    aisle(row, 20),
    ...segment(row, 21, 24, occupied),
  ];
}

function isBookable(slot: Slot): slot is Bookable {
  return slot.kind === 'seat' || slot.kind === 'couch';
}

/** Seats taken by an element: a couch is two seats. */
function seatsIn(slot: Bookable): number {
  return slot.kind === 'couch' ? 2 : 1;
}

@Component({
  selector: 'app-seat-selection',
  imports: [MatButtonModule],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(CinemaApi);
  private readonly router = inject(Router);
  private readonly title = inject(Title);
  private readonly toast = inject(Toast);

  /** Bound from the `id` route parameter. */
  readonly id = input.required<string>();

  protected readonly legend = LEGEND;

  /** Keys of the selected seats and couches. */
  private readonly selection = signal<ReadonlySet<string>>(new Set());

  protected readonly data = resource({
    params: () => this.id(),
    loader: async ({ params: id }): Promise<SeatMapData> => {
      this.selection.set(new Set());
      const screening = await this.api.getScreening(Number(id));
      const movie = await this.api.getMovie(screening.movieId);
      return { movie, screening, showDate: formatShowDate(screening.date, screening.time) };
    },
  });

  protected readonly rows = computed<SeatMapRow[]>(() => {
    const data = this.data.value();
    if (!data) {
      return [];
    }
    const occupied = new Set(data.screening.occupiedSeats);
    return ROW_NUMBERS.map((number) => ({ number, slots: buildRow(number, occupied) }));
  });

  /** Selected elements in ascending row, then column order. */
  private readonly selectedSlots = computed<Bookable[]>(() => {
    const keys = this.selection();
    return this.rows()
      .flatMap((row) => row.slots)
      .filter(isBookable)
      .filter((slot) => keys.has(slot.key));
  });

  protected readonly selectedCount = computed(() =>
    this.selectedSlots().reduce((total, slot) => total + seatsIn(slot), 0),
  );

  protected readonly selectedRows = computed<SelectedRow[]>(() => {
    const labelsByRow = new Map<number, string[]>();
    for (const slot of this.selectedSlots()) {
      const label = slot.kind === 'couch' ? `${slot.start}-${slot.end}` : `${slot.column}`;
      labelsByRow.set(slot.row, [...(labelsByRow.get(slot.row) ?? []), label]);
    }
    return [...labelsByRow].map(([row, labels]) => ({ row, seats: labels.join(', ') }));
  });

  constructor() {
    effect(() => {
      if (this.data.error()) {
        this.router.navigate(['/']);
      }
    });
    effect(() => {
      const movie = this.data.value()?.movie;
      if (movie) {
        this.title.setTitle(`${movie.title} - Cinescope`);
      }
    });
  }

  /** The state a seat or couch is painted with: selected overrides its own state. */
  protected displayState(slot: Bookable): DisplayState {
    return this.selection().has(slot.key) ? 'selected' : slot.state;
  }

  protected toggle(slot: Bookable): void {
    if (slot.state === 'unavailable') {
      return;
    }
    const keys = this.selection();
    if (keys.has(slot.key)) {
      const next = new Set(keys);
      next.delete(slot.key);
      this.selection.set(next);
      return;
    }
    if (this.selectedCount() + seatsIn(slot) > MAX_SEATS) {
      this.toast.show(`Maximum ${MAX_SEATS} seats per booking`);
      return;
    }
    this.selection.set(new Set([...keys, slot.key]));
  }

  protected cancel(): void {
    this.router.navigate(['/']);
  }

  protected continueToSummary(): void {
    if (this.selectedCount() > 0) {
      this.router.navigate(['/screenings', this.id(), 'summary']);
    }
  }
}
==== seat-selection/seat-selection.html
<section class="seat-selection">
  <h1 data-testid="seat-map-title">Choose your seats</h1>

  @if (data.value(); as loaded) {
    <p class="subtitle" data-testid="seat-map-subtitle">Show Date: {{ loaded.showDate }}</p>

    <div class="auditorium">
      <p class="seat-limit" data-testid="seat-limit-info">You can reserve up to 10 seats per reservation</p>
      <div class="screen" data-testid="screen-indicator">SCREEN</div>

      <div class="seat-map" data-testid="seat-map">
        @for (row of rows(); track row.number) {
          <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.number">
            <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.number">{{ row.number }}</span>
            @for (slot of row.slots; track slot.key) {
              @if (slot.kind === 'seat') {
                <button
                  type="button"
                  class="seat"
                  data-testid="seat"
                  [attr.data-row]="slot.row"
                  [attr.data-column]="slot.column"
                  [attr.data-state]="displayState(slot)"
                  [disabled]="slot.state === 'unavailable'"
                  (click)="toggle(slot)"
                >{{ slot.column }}</button>
              } @else if (slot.kind === 'couch') {
                <button
                  type="button"
                  class="couch"
                  data-testid="couch"
                  [attr.data-row]="slot.row"
                  [attr.data-column-start]="slot.start"
                  [attr.data-column-end]="slot.end"
                  [attr.data-state]="displayState(slot)"
                  [disabled]="slot.state === 'unavailable'"
                  (click)="toggle(slot)"
                >{{ slot.start }}-{{ slot.end }}</button>
              } @else if (slot.kind === 'aisle') {
                <span class="aisle" data-testid="aisle" [attr.data-row]="slot.row"></span>
              } @else {
                <span class="entrance" aria-hidden="true"></span>
              }
            }
            <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.number">{{ row.number }}</span>
          </div>
        }
      </div>
    </div>

    <ul class="legend" data-testid="legend">
      @for (item of legend; track item.state) {
        <li class="legend-item" data-testid="legend-item" [attr.data-state]="item.state"><span class="swatch" [attr.data-state]="item.state"></span>{{ item.label }}</li>
      }
    </ul>

    <section class="selected-seats" data-testid="selected-seats">
      <p class="selected-count" data-testid="selected-seats-count">Selected seats: {{ selectedCount() }}</p>
      @for (line of selectedRows(); track line.row) {
        <p class="selected-row" data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.seats }}</p>
      }
    </section>

    <div class="actions">
      <button type="button" matButton="outlined" data-testid="cancel-button" (click)="cancel()">Cancel</button>
      <button
        type="button"
        matButton="filled"
        data-testid="continue-button"
        [disabled]="selectedCount() === 0"
        (click)="continueToSummary()"
      >Continue</button>
    </div>
  }
</section>
==== seat-selection/seat-selection.scss
// One unit is the width of one seat column, including its margins.
$unit: 36px;

:host {
  display: block;
}

.seat-selection {
  margin: 0 auto;
  padding: 24px;
  text-align: center;

  h1 {
    margin: 0 0 8px;
    font-size: 1.75rem;
  }
}

.subtitle {
  margin: 0 0 16px;
  color: #57606a;
}

.auditorium {
  width: fit-content;
  margin: 0 auto;
}

.seat-limit {
  margin: 0 0 12px;
  text-align: center;
}

.screen {
  width: 70%;
  margin: 0 auto 20px;
  padding: 4px 0;
  border-radius: 4px;
  background: #e0e0e0;
  color: #424242;
  font-size: 0.8rem;
  letter-spacing: 0.3em;
}

.seat-row {
  display: flex;
  align-items: center;
  margin-bottom: 4px;
}

.row-label {
  flex: none;
  width: $unit;
  color: #57606a;
  font-size: 12px;
  text-align: center;
}

.entrance {
  flex: none;
  width: $unit * 4;
}

.aisle {
  flex: none;
  width: $unit * 2;
}

// Colours depend on the state only, so hover and focus never change them.
@mixin state-colours {
  &[data-state='available'] {
    background-color: #2e7d32;
  }

  &[data-state='selected'] {
    background-color: #f9a825;
    color: #212121;
  }

  &[data-state='unavailable'] {
    background-color: #c62828;
  }

  &[data-state='accessible'] {
    background-color: #1565c0;
  }
}

.seat,
.couch {
  flex: none;
  height: 32px;
  margin: 0 2px;
  padding: 0;
  border: 0;
  color: #fff;
  font-size: 12px;
  cursor: pointer;

  &:disabled {
    cursor: not-allowed;
  }

  @include state-colours;
}

.seat {
  width: $unit - 4px;
  border-radius: 6px 6px 2px 2px;
}

.couch {
  width: $unit * 2 - 4px;
  border-radius: 10px 10px 4px 4px;
}

.legend {
  display: flex;
  justify-content: center;
  gap: 24px;
  margin: 20px 0 0;
  padding: 0;
  list-style: none;
}

.legend-item {
