      <div class="screen" data-testid="screen-indicator">SCREEN</div>

      <div class="seat-map" data-testid="seat-map">
        @for (row of rows(); track row.number) {
          <div class="seat-row" data-testid="seat-row" [attr.data-row]="row.number">
            <span class="row-label" data-testid="row-label-left" [attr.data-row]="row.number">{{ row.number }}</span>
            @for (slot of row.slots; track slot.key) {
              @if (slot.kind === 'seat') {
                <button
                  type="button"
                  class="seat"
                  data-testid="seat"
                  [attr.data-row]="slot.row"
                  [attr.data-column]="slot.column"
                  [attr.data-state]="displayState(slot)"
                  [disabled]="slot.state === 'unavailable'"
                  (click)="toggle(slot)"
                >{{ slot.column }}</button>
              } @else if (slot.kind === 'couch') {
                <button
                  type="button"
                  class="couch"
                  data-testid="couch"
                  [attr.data-row]="slot.row"
                  [attr.data-column-start]="slot.start"
                  [attr.data-column-end]="slot.end"
                  [attr.data-state]="displayState(slot)"
                  [disabled]="slot.state === 'unavailable'"
                  (click)="toggle(slot)"
                >{{ slot.start }}-{{ slot.end }}</button>
              } @else if (slot.kind === 'aisle') {
                <span class="aisle" data-testid="aisle" [attr.data-row]="slot.row"></span>
              } @else {
                <span class="entrance" aria-hidden="true"></span>
              }
            }
            <span class="row-label" data-testid="row-label-right" [attr.data-row]="row.number">{{ row.number }}</span>
          </div>
        }
      </div>
    </div>

    <ul class="legend" data-testid="legend">
      @for (item of legend; track item.state) {
        <li class="legend-item" data-testid="legend-item" [attr.data-state]="item.state"><span class="swatch" [attr.data-state]="item.state"></span>{{ item.label }}</li>
      }
    </ul>

    <section class="selected-seats" data-testid="selected-seats">
      <p class="selected-count" data-testid="selected-seats-count">Selected seats: {{ selectedCount() }}</p>
      @for (line of selectedRows(); track line.row) {
        <p class="selected-row" data-testid="selected-seats-row" [attr.data-row]="line.row">Row {{ line.row }}: {{ line.seats }}</p>
      }
    </section>

    <div class="actions">
      <button type="button" matButton="outlined" data-testid="cancel-button" (click)="cancel()">Cancel</button>
      <button
        type="button"
        matButton="filled"
        data-testid="continue-button"
        [disabled]="selectedCount() === 0"
        (click)="continueToSummary()"
      >Continue</button>
    </div>
  }
</section>
