protected toggle(slot: Bookable): void {
  if (slot.state === 'unavailable') {
    return;
  }
  const items = this.bookings.booking()?.items ?? [];
  if (this.selection().has(slot.key)) {
    this.bookings.setItems(items.filter((item) => itemKey(item) !== slot.key));
