await tid('terms-checkbox').locator('input').click({ force: true }); await settle();
log('terms after input click checked?', await tid('terms-checkbox').locator('input').isChecked());
const el = await page.evaluate(() => {
  const host = document.querySelector('[data-testid="terms-checkbox"]');
  const r = host.getBoundingClientRect();
  const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
  const top = document.elementFromPoint(cx, cy);
  return { centre: [cx, cy], hit: top?.tagName + '.' + top?.className, hostWidth: r.width, hostHeight: r.height };
});
log('CENTRE HIT', JSON.stringify(el));
log('PAGE ERRORS', JSON.stringify(errors));
await browser.close();

