    89	    slots.push({
    90	      kind: 'seat',
    91	      key: `seat-${row}-${column}`,
    92	      row,
    93	      column,
    94	      state: seatState(row, column, occupied),
    95	    });
    96	  }
    97	  return slots;
    98	}
