const fs=require('fs');const d=require('/workspace/project/db.json');
const base=Date.UTC(2026,8,15);const now=new Date();const today=Date.UTC(now.getFullYear(),now.getMonth(),now.getDate());
const fmt=t=>new Date(t).toISOString().slice(0,10);
d.screenings=d.screenings.map(s=>({...s,date:fmt(today+(Date.parse(s.date)-base))}));
fs.writeFileSync('/tmp/e2e/db.json',JSON.stringify(d,null,2));
console.log(d.screenings.slice(0,3).map(s=>s.date+' '+s.time), fmt(today));
" && (nohup ./node_modules/.bin/json-server --watch /tmp/e2e/db.json --port 3000 > /tmp/e2e/api.log 2>&1 &) && (NX_DAEMON=false nohup ./node_modules/.bin/nx serve cinescope --port 4200 > /tmp/e2e/serve.log 2>&1 &) ; sleep 25; curl -s localhost:3000/movies | head -c 300; echo; tail -5 /tmp/e2e/serve.log

