    19	
    20	@Component({
    21	  selector: 'app-summary',
    22	  imports: [MatButtonModule],
    23	  templateUrl: './summary.html',
    24	  styleUrl: './summary.scss',
    25	})
    26	export class Summary {
    27	  private readonly api = inject(CinemaApi);
    28	  private readonly bookings = inject(BookingStore);
    29	  private readonly router = inject(Router);
    30	
    31	  /** Bound from the `id` route parameter. */
    32	  readonly id = input.required<string>();
    33	
    34	  protected readonly data = resource({
    35	    params: () => this.id(),
    36	    loader: async ({ params: id }): Promise<SummaryData> => {
    37	      const screening = await this.api.getScreening(Number(id));
    38	      const movie = await this.api.getMovie(screening.movieId);
    39	      return { movie, screening };
    40	    },
    41	  });
    42	
    43	  protected readonly lines = computed<SummaryLine[]>(() =>
    44	    (this.bookings.booking()?.items ?? []).map((item) => ({
    45	      key: itemKey(item),
    46	      item,
    47	      seat: item.couch ? `Couch ${item.column}-${item.column + 1}` : `${item.column}`,
    48	      price: formatPrice(priceOf(item)),
    49	    })),
    50	  );
    51	
    52	  protected readonly total = computed(
    53	    () => `Total: ${formatPrice(totalPrice(this.bookings.booking()?.items ?? []))}`,
    54	  );
    55	
    56	  constructor() {
    57	    effect(() => {
    58	      if (this.data.error()) {
    59	        this.router.navigate(['/']);
    60	      }
    61	    });
    62	  }
    63	
    64	  /** Takes one seat or couch out of the booking; opens the seat map when none is left. */
    65	  protected remove(key: string): void {
    66	    const remaining = (this.bookings.booking()?.items ?? []).filter((item) => itemKey(item) !== key);
    67	    this.bookings.setItems(remaining);
    68	    if (remaining.length === 0) {
    69	      this.toSeats();
    70	    }
    71	  }
    72	
    73	  protected back(): void {
    74	    this.toSeats();
    75	  }
    76	
    77	  protected confirm(): void {
    78	    this.router.navigate(['/screenings', this.id(), 'checkout']);
    79	  }
    80	
    81	  private toSeats(): void {
    82	    this.router.navigate(['/screenings', this.id(), 'seats']);
    83	  }
    84	}
