log('unavailable seat disabled', occ ? await occ.isDisabled() : 'none');

// Checkout: checkbox behaviour
await page.goto(BASE + '/screenings/' + sid + '/seats');
await page.waitForSelector('[data-testid="seat-map"]');
await page.locator('[data-testid="seat"][data-row="6"][data-column="5"]').click(); await settle();
await tid('continue-button').click();
await page.waitForURL(/summary/);
await page.waitForSelector('[data-testid="summary-item"]');
await tid('confirm-button').click();
await page.waitForURL(/checkout/);
await page.waitForSelector('[data-testid="terms-checkbox"]');
const box = await tid('terms-checkbox').boundingBox();
log('TERMS box', JSON.stringify(box));
await tid('terms-checkbox').click(); await settle();
log('terms after host click checked?', await tid('terms-checkbox').locator('input').isChecked(), 'error', await tid('terms-error').count());
await page.locator('[data-testid="terms-label"]').click(); await settle();
log('terms after label click checked?', await tid('terms-checkbox').locator('input').isChecked());
await tid('terms-checkbox').locator('input').click({ force: true }); await settle();
log('terms after input click checked?', await tid('terms-checkbox').locator('input').isChecked());
const el = await page.evaluate(() => {
  const host = document.querySelector('[data-testid="terms-checkbox"]');
  const r = host.getBoundingClientRect();
  const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
  const top = document.elementFromPoint(cx, cy);
  return { centre: [cx, cy], hit: top?.tagName + '.' + top?.className, hostWidth: r.width, hostHeight: r.height };
});
log('CENTRE HIT', JSON.stringify(el));
log('PAGE ERRORS', JSON.stringify(errors));
await browser.close();

