await tid('first-name-input').fill('Anna'); await tid('last-name-input').fill('Kowalska');
await tid('email-input').fill('anna@example.com'); await tid('confirm-email-input').fill('anna@example.com');
await page.locator('[data-testid="terms-label"]').click(); await settle();

